out.push("\n\n这里的手动模式采用 APG 示例的做法：已选中的 Tab 作为常规 Tab 入口，方向键可以将程序化焦点移动到其他 `tabindex=\"-1\"` 的 Tab。\n\n这也说明：\n\n**Focus 和 Selection 是两个不同的概念，不能在所有组件中将它们视为同一个状态。**\n\n### 2.4 Tabs 键盘交互规范\n\n| 按键 | 横向 Tabs | 纵向 Tabs |\n|---|---|---|\n| Tab | 进入或离开标签栏 | 相同 |\n| ArrowLeft | 上一个 Tab | 通常不处理 |\n| ArrowRight | 下一个 Tab | 通常不处理 |\n| ArrowUp | 保留默认行为 | 上一个 Tab |\n| ArrowDown | 保留默认行为 | 下一个 Tab |\n| Home | 第一个 Tab，可选 | 相同 |\n| End | 最后一个 Tab，可选 | 相同 |\n| Enter / Space | 手动激活 | 相同 |\n\n纵向 Tabs 还需要声明：\n\n```html\n<div\n  role=\"tablist\"\n  aria-label=\"Product information\"\n  aria-orientation=\"vertical\"\n>\n  ...\n</div>\n```\n\n横向是默认方向，可以省略 `aria-orientation=\"horizontal\"`。\n\n尤其注意，不要在横向 Tabs 中无条件拦截上下方向键，否则可能影响用户正常滚动页面。\n\n---\n\n## 3. 封装可复用的 Tabs Web Component\n\n结合 Shopify Theme 的开发方式，我们可以通过原生 JavaScript 和 Custom Element 实现一个通用组件。\n\n### 3.1 HTML\n\n```html\n<accessible-tabs activation=\"manual\">\n\n  <div role=\"tablist\" aria-label=\"Product information\">\n    <button\n      type=\"button\"\n      role=\"tab\"\n      id=\"DescriptionTab\"\n      aria-controls=\"DescriptionPanel\"\n      aria-selected=\"true\"\n      tabindex=\"0\"\n    >\n      Description\n    </button>\n\n    <button\n      type=\"button\"\n      role=\"tab\"\n      id=\"ReviewsTab\"\n      aria-controls=\"ReviewsPanel\"\n      aria-selected=\"false\"\n      tabindex=\"-1\"\n    >\n      Reviews\n    </button>\n  </div>\n\n  <div\n    role=\"tabpanel\"\n    id=\"DescriptionPanel\"\n    aria-labelledby=\"DescriptionTab\"\n    tabindex=\"0\"\n  >\n    Product description\n  </div>\n\n  <div\n    role=\"tabpanel\"\n    id=\"ReviewsPanel\"\n    aria-labelledby=\"ReviewsTab\"\n    tabindex=\"0\"\n    hidden\n  >\n    Customer reviews\n  </div>\n\n</accessible-tabs>\n```\n\n通过 `activation=\"manual\"` 或 `activation=\"auto\"` 控制激活方式。\n\n### 3.2 JavaScript\n\n创建 `assets/accessible-tabs.js`：\n\n```javascript\nclass AccessibleTabs extends HTMLElement {\n  connectedCallback() {\n    if (this.controller) return;\n\n    this.tablist = this.querySelector('[role=\"tablist\"]');\n    if (!this.tablist) return;\n\n    this.tabs = Array.from(\n      this.tablist.querySelectorAll('[role=\"tab\"]')\n    );\n\n    this.panels = this.tabs.map(tab =>\n      document.getElementById(\n        tab.getAttribute('aria-controls')\n      )\n    );\n\n    if (\n      !this.tabs.length ||\n      this.panels.some(panel =>\n        !panel || !this.contains(panel)\n      )\n    ) return;\n\n    this.controller = new AbortController();\n    const signal = this.controller.signal;\n\n    this.tabs.forEach((tab, index) => {\n      tab.addEventListener('click', () => {\n        this.activate(index);\n      }, { signal });\n\n      tab.addEventListener('keydown', event => {\n        this.onKeydown(event, index);\n      }, { signal });\n\n      tab.addEventListener('focus', () => {\n        if (this.getAttribute('activation') === 'auto') {\n          this.activate(index);\n        }\n      }, { signal });\n    });\n\n    const selected = this.tabs.findIndex(tab =>\n      tab.getAttribute('aria-selected') === 'true'\n    );\n\n    this.activate(Math.max(0, selected));\n  }\n\n  activate(index) {\n    if (!this.tabs[index]) return;\n\n    this.tabs.forEach((tab, i) => {\n      const selected = i === index;\n\n      // 如果旧面板即将隐藏，先移出其内部焦点\n      if (\n        !selected &&\n        this.panels[i].contains(document.activeElement)\n      ) {\n        this.tabs[index].focus();\n      }\n\n      tab.setAttribute(\n        'aria-selected',\n        String(selected)\n      );\n\n      tab.tabIndex = selected ? 0 : -1;\n\n      this.panels[i].hidden = !selected;\n    });\n\n    this.selectedIndex = index;\n  }\n\n  onKeydown(event, index) {\n    const vertical =\n      this.tablist.getAttribute('aria-orientation')\n        === 'vertical';\n\n    const previous = vertical\n      ? 'ArrowUp'\n      : 'ArrowLeft';\n\n    const next = vertical\n      ? 'ArrowDown'\n      : 'ArrowRight';\n\n    const length = this.tabs.length;\n    let target;\n\n    switch (event.key) {\n      case previous:\n        target = (index - 1 + length) % length;\n        break;\n\n      case next:\n        target = (index + 1) % length;\n        break;\n\n      case 'Home':\n        target = 0;\n        break;\n\n      case 'End':\n        target = length - 1;\n        break;\n\n      default:\n        return;\n    }\n\n    event.preventDefault();\n\n    this.tabs[target].focus();\n  }\n\n  disconnectedCallback() {\n    this.controller?.abort();\n    this.controller = null;\n  }\n}\n\nif (!customElements.get('accessible-tabs')) {\n  customElements.define(\n    'accessible-tabs',\n    AccessibleTabs\n  );\n}\n```\n\n为什么代码没有单独监听 Enter 和 Space？\n\n因为 Tab 使用的是原生 button。浏览器已经实现键盘激活，Enter 和 Space 可以触发 click 事件，因此无需重复实现。\n\n### 3.3 CSS：区分选中状态与焦点状态\n\n```css\naccessible-tabs {\n  display: block;\n}\n\n[role=\"tablist\"] {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n[role=\"tab\"] {\n  padding: 12px 16px;\n  background: transparent;\n  color: inherit;\n  border: 0;\n  border-bottom: 3px solid transparent;\n  cursor: pointer;\n}\n\n[role=\"tab\"][aria-selected=\"true\"] {\n  border-bottom-color: currentColor;\n  font-weight: 700;\n}\n\n[role=\"tab\"]:focus-visible {\n  outline: 2px solid currentColor;\n  outline-offset: 2px;\n}\n\n[role=\"tabpanel\"] {\n  padding-block: 16px;\n}\n\n[role=\"tabpanel\"][hidden] {\n  display: none !important;\n}\n\n[role=\"tabpanel\"]:focus-visible {\n  outline: 2px solid currentColor;\n}\n```\n\n选中状态使用下划线和字重，焦点状态使用 outline。即使两个状态同时出现，用户也能够区分。\n\n这是一个静态 DOM 的基础组件实现。若需要动态增加、删除 Tab、支持嵌套 Tabs 或 RTL 布局，需要进一步扩展；正式项目也应考虑 JavaScript 加载失败时显示全部内容的渐进增强方案。\n\n---\n\n## 4. Accordion：手风琴组件\n\nAccordion 与上一课学习的 Disclosure 有非常紧密的关系。\n\n一个 Disclosure 负责展开或折叠一个区域，而 Accordion 通常是多个 Disclosure 的组合。\n\nShopify 中常见的应用包括 FAQ、商品详情、配送政策、退换货说明以及移动端 Collection 筛选区域。\n\n### 4.1 三种 Accordion 模式\n\n| 模式 | 行为 |\n|---|---|\n| Multiple | 允许同时展开多个面板 |\n| Exclusive | 最多展开一个面板 |\n| Required Open | 始终至少有一个面板展开 |\n\n");
